/* rrg_features.js — the shared "What this section does" strip.
   One component for every page in the sidebar so the strip looks and behaves the same everywhere.

   On a page:   <div data-rrg-feats="calendar"></div>   +   <script src="/rrg_features.js"></script>
   The strip draws itself into that placeholder from the registry below (window.RRG_FEATS).
   Each tile opens that feature's help: a section of the page's dedicated guide when one exists
   (feat.href), otherwise the generated guide  rrg_guide.html?p=<key>#<feature id>.
   Collapsed by default; the open/closed choice is remembered per page (a UI convenience only). */
/* Registry — one entry per sidebar section. Keep feature ids stable: help links use them. */
window.RRG_FEATS = {"brief":{"label":"Daily Brief","group":"My Work","page":"rrg_brief.html","sub":"your pipeline read every morning and boiled down to what to do today","guide":"","feats":[{"id":"today","ic":"🎯","t":"Do today, ranked by urgency","d":"Three to seven moves that make or protect money today, most urgent first, each tagged high, med or low."},{"id":"reads","ic":"📚","t":"Reads your whole pipeline","d":"Listing expirations, deals closing, commissions owed, agreements lapsing in 60 days, recent LOIs and overdue tasks."},{"id":"week","ic":"🗓️","t":"Week ahead and one play to win","d":"Up to five heads-up items for the rest of the week plus one sharp strategic line on where to push."},{"id":"spaces","ic":"🏬","t":"New space fits for your tenants","d":"Spaces added in the last week that score as a fit for one of your tenant-rep clients get called out."},{"id":"rerun","ic":"⏱️","t":"Last brief on open, Refresh for new","d":"Opening the page shows your last brief while it's current; ↻ Refresh runs a new one, and a run can be cancelled midway."},{"id":"scope","ic":"👥","t":"Run anyone's brief","d":"Admins and anyone with See all records switch between Mine, Everyone (firm-wide) or one rep's book, and can link straight to it.","admin":true}]},"inbox":{"label":"Review","group":"My Work","page":"rrg_inbox.html","sub":"leads, record updates and attachments read from your inbox, waiting for your ok","guide":"","feats":[{"id":"leads","ic":"📥","t":"Leads read from your inbox","d":"Label an email in Gmail and the AI pulls the sender's name, title, phone and company into a pre-filled lead card."},{"id":"confirm","ic":"✅","t":"Nothing lands without your ok","d":"Fix any field, then Confirm & add or Dismiss — the contact, company, note and follow-up plan are set up in one click."},{"id":"updates","ic":"✏️","t":"Updates to contacts you know","d":"Email from an existing contact becomes a before → after list of changes to their record or open deal; tick the ones to apply."},{"id":"files","ic":"📎","t":"Attachments filed to the deal","d":"PDF and Word attachments on labeled email are proposed for the Doc Vault, pre-pointed at the sender's open deal or contact."},{"id":"scan","ic":"🔄","t":"Scan now or let it watch","d":"Pull labeled email on demand with Scan now, or turn on auto-intake on your Account page to check on a schedule."},{"id":"autoadd","ic":"⚡","t":"Confirm before adding switch","d":"Leave it on to review every lead; turn it off and new leads go straight into your book."},{"id":"recent","ic":"🕘","t":"Recently handled","d":"The last 30 items you added, updated, filed or dismissed, each with a link back to the contact."}]},"tasks":{"label":"Tasks","group":"My Work","page":"rrg_tasks.html","sub":"every follow-up you owe, tied to the contact or listing, with reminders and repeats","guide":"","feats":[{"id":"create","ic":"➕","t":"Add a task in seconds","d":"Title, due date and time, priority and owner — the title box suggests your most-used phrases like Send NDA to or Schedule tour with."},{"id":"link","ic":"🔗","t":"Tied to the contact or listing","d":"Link a task to a contact or a listing and the Contact and Company columns fill in, with a click-through to the record."},{"id":"done","ic":"☑️","t":"Check it off","d":"Tick the box to complete a task; switch between Open, Done and All to see what's left, what you finished, or both."},{"id":"repeat","ic":"🔁","t":"Repeating tasks","d":"Daily, weekly, every 2 weeks, monthly, last day of the month, quarterly or yearly — the next one appears on its own."},{"id":"remind","ic":"🔔","t":"Reminders by pop-up, email or text","d":"Get nudged at the due time, 10 minutes to a day before, or any custom time — in the browser, by email or by SMS."},{"id":"inline","ic":"✍️","t":"Edit right in the list","d":"Click a task's title or priority to change it in place; open Edit and changes save as you type."},{"id":"bulk","ic":"📦","t":"Bulk complete or delete","d":"Tick several rows and mark them all complete or delete them in one go."},{"id":"tools","ic":"🧰","t":"Search, filter, save and export","d":"Search across title, notes, contact and company; filter by column, save the setup, pick columns, export to CSV or print."},{"id":"cleanup","ic":"🧹","t":"Clear completed imports","d":"One click deletes finished tasks that aren't tied to any contact or listing — the clutter left by bulk imports."},{"id":"everyone","ic":"👥","t":"Everyone's tasks","d":"Admins switch from My tasks to Everyone to see and manage the whole team's follow-ups.","admin":true}]},"calendar":{"label":"Calendar","group":"My Work","page":"rrg_calendar.html","sub":"every meeting, tour and call for you and the team, with invites, reminders and booking","guide":"rrg_calendar_help.html","feats":[{"id":"schedule","ic":"📅","t":"Book a meeting in seconds","d":"Title, contact, type, time and a place search that finds restaurants and addresses as you type — or click any day to start.","href":"rrg_calendar_help.html#schedule"},{"id":"views","ic":"🔭","t":"Day, Week, Month or Agenda","d":"Four views of the same schedule, a mini calendar to jump to any date, and each rep in their own color.","href":"rrg_calendar_help.html#views"},{"id":"invites","ic":"✉️","t":"Real invites to outside guests","d":"Add anyone by name and email and send a calendar invite they can drop into Outlook or Google — no account needed.","href":"rrg_calendar_help.html#invites"},{"id":"reminders","ic":"🔔","t":"Reminders so nobody no-shows","d":"Up to 8 reminders, from start time to a week before, by pop-up, email or text — invited guests get an email reminder too.","href":"rrg_calendar_help.html#reminders"},{"id":"recurring","ic":"🔁","t":"Repeating meetings","d":"Weekly, every 2 weeks or monthly for a set number of times; delete just one or this one and everything after.","href":"rrg_calendar_help.html#recurring"},{"id":"scope","ic":"👥","t":"Whole team, one rep, or just you","d":"Flip between everyone's calendar, a single teammate's or only your meetings, and see each person's working hours.","href":"rrg_calendar_help.html#scope"},{"id":"meet","ic":"🎥","t":"Google Meet in one click","d":"Mint a real Google Meet link on any meeting; it's copied into the invite your guests get.","href":"rrg_calendar_help.html#meet"},{"id":"gsync","ic":"⟳","t":"Two-way Google Calendar sync","d":"Click Google in the toolbar to pull new and changed events from your Google Calendar and push your meetings out."},{"id":"notetaker","ic":"🎙️","t":"Record it, get an AI recap","d":"Record a call or meeting from the event and get a transcript plus a recap of decisions, action items and numbers.","href":"rrg_calendar_help.html#notetaker"},{"id":"booking","ic":"🔗","t":"Online bookings land here","d":"Meetings booked through your booking link drop straight onto your calendar, flagged Booked online, with a count in the nav.","href":"rrg_calendar_help.html#booking"},{"id":"automation","ic":"⚙️","t":"Kick off a follow-up plan","d":"Choose an automation when you schedule and the contact or guest is enrolled in it the moment you save."},{"id":"emails","ic":"📧","t":"Email blasts on the calendar","d":"Scheduled and sent email campaigns sit beside your meetings, with sent, open and click counts.","href":"rrg_calendar_help.html#emails"}]},"feed":{"label":"Feed","group":"My Work","page":"rrg_feed.html","sub":"what moved across your book, who's in your data rooms and what needs you next","guide":"rrg_feed_help.html","feats":[{"id":"stream","ic":"🗞️","t":"Your whole book, one stream","d":"Calls, tours, notes, emails, agreements and LOIs across every contact, newest first — click a row to open the contact.","href":"rrg_feed_help.html#stream"},{"id":"buyers","ic":"🔥","t":"Who's in your data rooms","d":"See when a buyer opens the P&L, tax returns, lease or CIM — those visits are flagged Hot so you call while it's warm.","href":"rrg_feed_help.html#buyers"},{"id":"moving","ic":"🎯","t":"Keep things moving","d":"A ranked to-do rail: overdue tasks, hot and cooling buyers, emails waiting on a reply and buyers or sellers gone quiet.","href":"rrg_feed_help.html#moving"},{"id":"calendar","ic":"📅","t":"Meetings on the timeline","d":"Meetings, tours and calls from the last two months through the next three weeks, with upcoming ones tagged.","href":"rrg_feed_help.html#calendar"},{"id":"glance","ic":"📊","t":"Your week at a glance","d":"The left rail tallies this week's meetings, calls, agreements, tours and hot buyers, lists what's next and counts your pipeline."},{"id":"filters","ic":"🎛️","t":"Filter any way you work","d":"By date range, by one contact, company or listing, by several activity types at once, and by teammate.","href":"rrg_feed_help.html#filters"},{"id":"views","ic":"🔖","t":"Saved views","d":"Save the filters you use most — date, type, contact, user and the system toggle — and jump back in one click.","href":"rrg_feed_help.html#views"},{"id":"quiet","ic":"🔕","t":"Signal over noise","d":"Automated churn is hidden by default and repeated system rows fold into one · +N more line.","href":"rrg_feed_help.html#quiet"},{"id":"suggested","ic":"➕","t":"People worth adding","d":"People you've emailed in the last two months who aren't in your book yet — add them with one click.","href":"rrg_feed_help.html#suggested"}]},"companies":{"label":"Companies","group":"Book of Business","page":"rrg_companies.html","sub":"every operator in your book, with its concepts, locations, contacts and listings","guide":"","feats":[{"id":"newco","ic":"⚡","t":"Set up a company in one pass","d":"Company, owner, metros, first contact, pipeline and concept names in one window — the record opens ready to work."},{"id":"paste","ic":"📋","t":"Paste a signature, get the fields","d":"Drop an email signature or business card text into Paste to fill and AI splits it into company and contact fields."},{"id":"dupes","ic":"🛑","t":"Duplicate guard as you type","d":"An exact match blocks Create and links to the existing file; close matches show a \"did you mean\" list."},{"id":"aibuild","ic":"✨","t":"AI builds concepts & locations","d":"Type the brand names — or tick Restaurant group — and AI fills each concept's website, type, cuisine, price, logo and locations."},{"id":"hierarchy","ic":"🏢","t":"Operator → concepts → locations","d":"Each company holds the brands it runs and each brand its units, plus commissaries — the real shape of a restaurant group."},{"id":"map","ic":"🗺️","t":"Locations map & Google data","d":"See every unit on one map colored by concept, and pull ratings, status and photos from Google onto each location."},{"id":"glance","ic":"📊","t":"Relationship value at a glance","d":"Interactions, last contacted, inactive days, active listings, closed deals and commission earned sit atop every company file."},{"id":"activity","ic":"🗒️","t":"Activity log & notes","d":"Log calls, tours and meetings or drop a note on the company; a To-Do becomes a task assigned to the rep you pick."},{"id":"linked","ic":"🔗","t":"Contacts, listings & files in one file","d":"Link people, star the main contact, open each listing or set up its data room, and keep documents and files on the company."},{"id":"list","ic":"🔎","t":"Recent-first list, filters & edits","d":"See companies active lately with one click to show all, filter by type, market, owner, tags or date, and fix names right in the list."},{"id":"admin","ic":"🛠️","t":"Bulk owner change & merge","d":"Select companies to hand them to another rep or fold duplicates into one record with every contact and listing moved over.","admin":true}]},"people":{"label":"Contacts","group":"Book of Business","page":"rrg_people.html","sub":"every buyer, seller, tenant and landlord in your book, with what they want and every touch","guide":"rrg_contacts_help.html","feats":[{"id":"buybox","ic":"🎯","t":"Buy-box & listing matches","d":"Save what a buyer is after — concept, market, price, SDE, units — and the record lists the current listings that fit, with reasons.","href":"rrg_contacts_help.html#buybox"},{"id":"tenantbox","ic":"📐","t":"Tenant-box & space matches","d":"Capture a tenant's size, condition, amenities, markets and budget — or fill it from their Site Criteria — and see sites that fit.","href":"rrg_contacts_help.html#tenantbox"},{"id":"selleractions","ic":"🧭","t":"Seller path, step by step","d":"Biz Seller Actions walks a seller from screening call to interview, valuation, listing agreement and market, checking off each step.","href":"rrg_contacts_help.html#screening"},{"id":"tenantrep","ic":"🏬","t":"Tenant Rep Actions","d":"Start a tenant's space search on the Tenant Rep pipeline, capture their Site Criteria, and add an exclusive agreement only if wanted."},{"id":"feed","ic":"🗒️","t":"Every touch in one feed","d":"Log calls and notes, send email through your Gmail with a saved template, and it all lands on one filterable timeline.","href":"rrg_contacts_help.html#comms"},{"id":"prep","ic":"✨","t":"AI call prep","d":"One click reads the record — recent activity, listings, agreements — and hands you a snapshot, openers and what to watch out for."},{"id":"tasks","ic":"📅","t":"Tasks & meetings with reminders","d":"Add follow-ups with one-tap due times and book meetings with a reminder and an emailed calendar invite."},{"id":"automations","ic":"⟳","t":"Drop them into an automation","d":"Enroll a contact in one of your firm's automations from their record, then pause, resume or stop it there."},{"id":"value","ic":"📊","t":"Relationship value at a glance","d":"Closed deals, transaction volume and commission generated sit on the record, so a repeat client never looks like a cold lead.","href":"rrg_contacts_help.html#value"},{"id":"flags","ic":"🚩","t":"Flags & quick edits on the list","d":"Toggle VIP, Star and Bad news right in the list, set the primary contact, and edit description, interests and last contacted in place.","href":"rrg_contacts_help.html#flags"},{"id":"bbs","ic":"🧲","t":"BizBuySell leads on autopilot","d":"Paste, upload or pull BizBuySell inquiries — each becomes a buyer contact, an inquiry on the right listing, and a follow-up task.","href":"rrg_contacts_help.html#import"},{"id":"filters","ic":"🔎","t":"Filters & saved searches","d":"Slice by interest, owner, lead source, tags, flags and dates, save the view for you or the team, and star one as your default.","href":"rrg_contacts_help.html#filters"},{"id":"admin","ic":"🛠️","t":"Merge duplicates & change owner","d":"Fold duplicate people into one record — emails, phones, tours, deals and agreements carried over — or reassign a batch to another rep.","admin":true}]},"documents":{"label":"Doc Vault","group":"Book of Business","page":"rrg_documents.html","sub":"every agreement, LOI, valuation, pack and upload your team has, in one list","guide":"","feats":[{"id":"library","ic":"📚","t":"One list for every document","d":"Agreements, LOIs, valuations, marketing packs, site criteria, screenings, lease abstracts, interviews and uploads — no filing needed."},{"id":"tabs","ic":"🗂️","t":"Type tabs with the right columns","d":"Each tab shows the fields that matter for that kind — effective and expiry dates on agreements, value and basis on valuations."},{"id":"filterbar","ic":"🎚️","t":"Filter by owner, type and date","d":"Narrow to one rep's documents, one document type, or what was created in the last week, month, quarter or year."},{"id":"hidesys","ic":"🙈","t":"Hide system docs","d":"One toggle hides agreements, LOIs, valuations, lease abstracts and every other tool-generated record so uploaded files and forms stand out."},{"id":"upload","ic":"⬆️","t":"Upload and link to a record","d":"Add any file up to 25 MB, give it a type, and tie it to a company, contact or listing so it's easy to find from the record."},{"id":"saved","ic":"★","t":"Saved views","d":"Save a tab, search and filter combination under ★ Saved and get back to it in one click."},{"id":"delete","ic":"🗑️","t":"Remove documents, one or many","d":"Delete a document with its ×, or tick several and choose Delete selected — it's removed at the source, not just from this list."},{"id":"firmwide","ic":"🏢","t":"Firm-wide forms","d":"Publish blank agreements, NDAs and onboarding decks once and they show for the whole team, on a Document, Agreement or Training shelf.","admin":true}]},"board":{"label":"Listings","group":"Business Sales","page":"rrg_board.html","sub":"every sell-side listing on one board, stage by stage, from first call to close","guide":"rrg_listings_help.html","when":[{"param":"pipelineId","value":"p_tenantrep","use":"board_tenant"}],"feats":[{"id":"drag","ic":"🔀","t":"Drag a card to change its stage","d":"Drop a listing in the next column and the stage saves on the spot — its days-in-stage clock starts over from today."},{"id":"newlisting","ic":"➕","t":"Start a listing in one step","d":"Name the business, pick the market, seller and owner — it builds the company, contact, data room and listing number for you."},{"id":"listview","ic":"☰","t":"Board or list, edit in place","d":"Flip to List for a sortable table — click a stage, status, owner, market, price or commission cell to change it right there."},{"id":"bulk","ic":"☑️","t":"Bulk-update a stack of listings","d":"Tick rows in List view and set status, stage, owner or market on all of them at once — or delete the batch."},{"id":"offboard","ic":"⇩","t":"Park a listing off the board","d":"Drag a stalled deal to Off the board and mark it On Hold, Lost or No Deal — it stays in its stage, out of your way."},{"id":"filters","ic":"🔎","t":"Filter and save your views","d":"Narrow by rep, markets, statuses and a dollar range, then save the combo by name to pull it back in one click."},{"id":"flags","ic":"🚩","t":"Flags for big and stalled deals","d":"A green $ marks listings above your value line; a red ! marks any card that has sat in its stage for its target days or more."},{"id":"cards","ic":"🧩","t":"Cards your way","d":"Sort each column, pick which fields show on each card, go Compact for a dense board, cap cards per column, and roll up ones you've read."},{"id":"value","ic":"💰","t":"Pipeline value at a glance","d":"Every column shows its count and dollar total, and the header adds up active listings, total value and how many are parked."},{"id":"open","ic":"📂","t":"Open a listing, then Prev / Next","d":"Click a card to open the full listing file; Prev and Next walk your filtered board in order, so you can review one by one.","href":"rrg_listings_help.html#overview"},{"id":"switch","ic":"🗂️","t":"Other boards and the marketplace","d":"The Pipeline menu swaps to any other board or the Buyers board; Marketplace opens your public confidential listings site."},{"id":"stages","ic":"🛠️","t":"Stages, targets and likelihood","d":"Admins set each pipeline's stages, the target days that drive the stalled flag, and the likelihood % for each stage.","admin":true}]},"buyer_board":{"label":"Buyers","group":"Business Sales","page":"rrg_buyer_board.html","sub":"every buyer lead on every listing, by stage — filter to one listing, drag to advance","guide":"","feats":[{"id":"pool","ic":"🗂️","t":"All your buyers on one board","d":"Every buyer lead across every listing, grouped by stage, with a live count per column and in the header."},{"id":"filter","ic":"🔎","t":"Zero in on one listing","d":"Type part of a listing's name to filter the board to its buyers — each choice shows how many buyers it has."},{"id":"drag","ic":"🔀","t":"Drag a buyer to the next stage","d":"Drop a card in a new column and that buyer's stage updates on its listing — no need to open the listing."},{"id":"offboard","ic":"⇩","t":"Park or drop a buyer","d":"Drag a cold buyer to Off the board, or use ··· on the card, to mark On Hold or Lost — their stage is kept for later."},{"id":"listview","ic":"☰","t":"List view with quick edits","d":"Switch to List for a sortable buyer table — change Stage or Status right in the row, filter it, and export it."},{"id":"cards","ic":"👤","t":"Cards that link to the source","d":"Each card shows company, email and lead source; the name opens the contact and the listing chip opens the listing."},{"id":"pipelines","ic":"🧭","t":"Switch buyer pipelines","d":"The Pipeline menu swaps between buyer pipelines, or jumps to any listing or tenant board."},{"id":"setup","ic":"🛠️","t":"Set up a buyer pipeline","d":"Admins create the buyer pipeline in Admin → Pipelines with Practice area set to Buyer; the board fills in from there.","admin":true}]},"rooms_queue":{"label":"Data Rooms","group":"Business Sales","page":"rrg_rooms_queue.html","sub":"every confidential deal room you run — who's in, what they opened, what's ready to share","guide":"rrg_dataroom_help.html","feats":[{"id":"status","ic":"🚦","t":"Every room's status at a glance","d":"Live, Shared and Setup badges plus quick-view chips show which rooms are loaded, which are in buyers' hands and which are empty.","href":"rrg_dataroom_help.html#overview"},{"id":"create","ic":"⚡","t":"New room with folders built in","d":"Name it, tie it to the seller and listing, and it opens with standard folders and five years of Financials and Tax folders.","href":"rrg_dataroom_help.html#create"},{"id":"upload","ic":"📁","t":"Upload once, auto-filed","d":"Upload files jumps straight to the upload panel; drop up to 40 files and the assistant files each one in the right folder.","href":"rrg_dataroom_help.html#upload"},{"id":"buyerview","ic":"👁️","t":"Preview the buyer side","d":"Buyer view opens the buyer side past the code gate — every folder shown, files open — without logging any buyer activity.","href":"rrg_dataroom_help.html#buyerview"},{"id":"link","ic":"🔗","t":"Copy the buyer link","d":"One click copies the private buyer link — once the room has documents or buyers, the link asks for a personal access code."},{"id":"access","ic":"🎚️","t":"Per-buyer codes and permissions","d":"Each buyer gets their own code and a level — none, view, download, upload — that you can override folder by folder.","href":"rrg_dataroom_help.html#permissions"},{"id":"engagement","ic":"📊","t":"Know which buyers are digging in","d":"See who opened which file, how long they read it, and a Hot flag on buyers who opened key financials and were active in the last 7 days.","href":"rrg_dataroom_help.html#analytics"},{"id":"alerts","ic":"🔔","t":"Alerts on key documents","d":"You're emailed the first time a buyer opens the P&L, financials, lease or tax returns — once per buyer per document.","href":"rrg_dataroom_help.html#alerts"},{"id":"questions","ic":"💬","t":"Answer buyer questions","d":"Buyers ask from inside the room; you reply on the room page and they're emailed that you answered — one private thread per buyer.","href":"rrg_dataroom_help.html#alerts"},{"id":"protect","ic":"🛡️","t":"Watermarks and redaction","d":"Downloaded PDFs are stamped with the buyer's name and email, and you can black out lines before buyers ever see a file.","href":"rrg_dataroom_help.html#protect"},{"id":"verify","ic":"🔑","t":"Two-step check for buyers","d":"A one-time email code on top of the access code — on by default, set per room; a verified device is trusted for 10 days.","href":"rrg_dataroom_help.html#verify"},{"id":"archive","ic":"🗄️","t":"Archive after the sale","d":"Closed rooms keep their history but drop out of the list — tick off Hide archived to see them again.","href":"rrg_dataroom_help.html#lifecycle"},{"id":"find","ic":"★","t":"Search, filters and saved views","d":"Find a room by name, rep or last visitor, filter by documents, dates or downloads, and save the setup you use most."}]},"deals":{"label":"Deals","group":"Business Sales","page":"rrg_deals.html","sub":"every buyer under contract — price, status, close date and the commission owed","guide":"","feats":[{"id":"tiles","ic":"📌","t":"Status tiles that filter","d":"Counts for under contract, closing, closed, commission due and paid across the top — click one to filter the list to it."},{"id":"open","ic":"🤝","t":"Open a deal on the listing","d":"+ New deal lists your listings without a deal yet and drops you on that listing's Deal card with the form open."},{"id":"form","ic":"📝","t":"Everything about the deal in one form","d":"Buyer, price, status from LOI to Closed, opened, expected and actual close, terms, notes and commission rate, due and paid."},{"id":"buyer","ic":"👤","t":"Buyer lands in your contacts","d":"Name the buyer (and email) on the deal and they're linked to — or added to — your contacts, so their record shows the deal."},{"id":"split","ic":"➗","t":"Co-broke & referral split preview","d":"Enter the co-broker's share and any referral off the top and the form shows the company dollar before you save."},{"id":"invoice","ic":"🧾","t":"Bill the commission","d":"Create invoice on the Deal card opens a new invoice pre-filled from the deal; the deal's commission status then follows its invoices."},{"id":"filters","ic":"🔎","t":"Search, filters & saved views","d":"Search by listing, buyer or status; filter by deal status, commission status and close date; save the view to pull up again."}]},"board_tenant":{"label":"Tenants","group":"Tenant Rep","page":"rrg_board.html?pipelineId=p_tenantrep","sub":"every tenant-rep search on one board, from needs analysis to grand opening","guide":"","feats":[{"id":"drag","ic":"🔀","t":"Drag a search to its next stage","d":"Drop a tenant in the next column — Site Search, Tours, LOI Out — and the stage saves on the spot with a fresh days-in-stage clock."},{"id":"newtenant","ic":"➕","t":"Open a new search in one step","d":"Name the concept, add every target market, pick the client and rep — it opens the engagement on the first stage."},{"id":"criteria","ic":"🎯","t":"Site criteria on every card","d":"Each card shows the size range, use, rent budget and target markets from the tenant's site criteria — no need to open the file."},{"id":"listview","ic":"☰","t":"Board or list, edit in place","d":"Flip to List for a sortable table — click a stage, status, owner or market cell to change it without opening the file."},{"id":"bulk","ic":"☑️","t":"Bulk-update several searches","d":"Tick rows in List view and set status, stage, owner or market on all of them at once — or delete the batch."},{"id":"offboard","ic":"⇩","t":"Park a search off the board","d":"Drag a quiet search to Off the board as On Hold, Lost or No Deal — it keeps its stage and leaves your columns."},{"id":"filters","ic":"🔎","t":"Filter and save your views","d":"Narrow by rep, market and status, search by concept or client, and save the combo under a name for one-click recall."},{"id":"flags","ic":"🚩","t":"Spot searches that stalled","d":"A red ! appears on any tenant that has sat in a stage for its target days or more, so dead-ending searches don't hide."},{"id":"cards","ic":"🧩","t":"Cards your way","d":"Sort each column, choose the fields each card shows, switch to Compact, cap cards per column, and roll up the ones you've read."},{"id":"open","ic":"📂","t":"Open the engagement file","d":"Click a card to open the full search — criteria, space shortlist, tours, site fit, LOIs, Market Attack Plan and lease."},{"id":"tours","ic":"📍","t":"Every tour in one list","d":"⊚ Tours in the toolbar lists every space shown across your tenant searches — filter by tenant or reaction, sort by rating."},{"id":"stages","ic":"🛠️","t":"Stages and target days","d":"Admins set the tenant-rep stages and how many days a search should sit in each before it's flagged as stalled.","admin":true}]},"ssc_form":{"label":"Site Criteria","group":"Tenant Rep","page":"ssc_form.html","sub":"capture a tenant's concept, markets, space, licensing and economics before any search","guide":"","feats":[{"id":"blueprint","ic":"🎯","t":"The search blueprint","d":"Seven sections cover concept, markets, space, TABC and zoning, economics and timeline — required items marked *."},{"id":"contact","ic":"🔗","t":"Start it from the contact","d":"Launch the SSC from a contact and it's linked to that client, the concept and contact fields fill in, and the send is logged on the record."},{"id":"send","ic":"📨","t":"Submit and email a branded PDF","d":"Checks every required field, then emails a branded SSC PDF to the tenant rep with a copy to the firm's address, and files it."},{"id":"print","ic":"🖨️","t":"Print it, or print a blank","d":"Print a branded SSC with a cover page, or print a blank copy to fill in by hand at a meeting."},{"id":"draft","ic":"💾","t":"Draft saves as you go","d":"Entries are kept in this browser and come back when you reopen the form, with a Start fresh button."},{"id":"reuse","ic":"♻️","t":"Feeds fit scoring and space matching","d":"A filed SSC prefills Site Fit, drives AI space matching on Spaces, and fills the contact's Tenant Box."}]},"space_tracker":{"label":"Spaces","group":"Tenant Rep","page":"rrg_space_tracker.html","sub":"every available space, scored for restaurant use and matched to your tenants","guide":"","feats":[{"id":"log","ic":"📍","t":"Log a space and its bones","d":"Address, center, size, base rent, NNN, position and status — tap the infrastructure already built so the space scores right."},{"id":"aifill","ic":"✨","t":"AI fill from a listing","d":"Paste a CoStar, LoopNet or Crexi blurb or broker email, or drop in PDFs — one fills the form, several each become a space."},{"id":"autoimport","ic":"📥","t":"Auto-import flyers from Gmail","d":"Watches your inbox for broker flyers and adds each space, files the PDF and creates the center — matched by address, no duplicates."},{"id":"ready","ic":"🍳","t":"Restaurant-ready score","d":"Scores 0–100 on what's built — hood, grease, gas, power, walk-in — and estimates the build-out a tenant avoids, in dollars."},{"id":"fits","ic":"🎯","t":"Tenant fits, automatically","d":"Every space is scored against your active tenant searches — size, area, budget, build needs — and new fits are posted to the feed."},{"id":"aimatch","ic":"🤖","t":"AI match to a client","d":"Pick a client's Site Criteria on file, or type what they want, and AI ranks every space with a score and a reason."},{"id":"sitefit","ic":"✚","t":"Run a Site Fit","d":"✚ Run Fit on a space page scores it for a concept — size, rent and NNN fill in, and the analysis stays listed on the space."},{"id":"map","ic":"🗺️","t":"Map view","d":"Flip to Map to see the filtered spaces pinned and colored by status; exact addresses are pinpointed in the background."},{"id":"survey","ic":"📄","t":"Market survey PDF","d":"Tick spaces and download a letterhead survey: map, summary table, then a page per space with photo, rents and ready score."},{"id":"comps","ic":"📊","t":"Rent comps","d":"Median asking, leased and NNN rents and days on market by market and position, plus every leased comp you've recorded."},{"id":"history","ic":"📉","t":"Price drops, stale listings, history","d":"Rent, NNN, size and status changes are logged; recent price drops, stale listings and long days on market are flagged."},{"id":"broker","ic":"✉️","t":"Request info or a tour","d":"One click on the space page emails the listing broker with your signature — opens tracked, logged, and reply time scored."},{"id":"siteintel","ic":"🥃","t":"Alcohol sales and nearby restaurants","d":"The space page pulls state mixed-beverage sales and TABC permits at the address, and the restaurants within about a mile."}]},"site_fit":{"label":"Site Fit","group":"Tenant Rep","page":"rrg_site_fit.html","sub":"score a space for a concept — occupancy test, weighted scorecard and a pursue-or-pass call","guide":"","feats":[{"id":"start","ic":"📍","t":"Start from a tenant and a space","d":"Click Fit on a space in a tenant’s shortlist, or Run Fit on a space — concept, size needed, rent, NNN and co-tenancy fill in."},{"id":"list","ic":"📋","t":"Every analysis in one list","d":"Search and sort every analysis by tenant, space, fit score, the call and occupancy — click a row to reopen it."},{"id":"moneytest","ic":"💰","t":"The occupancy-cost test","d":"Projects sales from check × guests × days, sets them against base + NNN, and shows the occupancy ratio in green, amber or red."},{"id":"scorecard","ic":"🎯","t":"Ten-factor weighted scorecard","d":"Rate demographics, daypart, co-tenancy, visibility, access, competition, space and more 1–5; weights reflect what makes F&B sites work."},{"id":"verdict","ic":"⚖️","t":"Pursue, workable or pass","d":"The sheet makes the call from the score — and a rent that doesn't pencil overrides a pretty site."},{"id":"narrative","ic":"🗒️","t":"Pros, risks and next steps","d":"Write why the site works, what to negotiate and the LOI ask right under the verdict, so the sheet is ready to send."},{"id":"print","ic":"🖨️","t":"Print or save a branded PDF","d":"Print gives a clean RRG-branded analysis with a cover, the numbers and the call — Save as PDF to send it."},{"id":"draft","ic":"💾","t":"Saved and linked as you type","d":"Each analysis saves to the server, linked to the tenant and the space — it shows on the tenant’s Site Fit card and the space page."},{"id":"prefill","ic":"⤓","t":"Fill from SSC / PDF — not yet","d":"The ↧ Fill from SSC / PDF button is on the toolbar, but auto-fill isn't available in this version yet — enter the fields by hand."}]},"loi_builder":{"label":"LOI Builder","group":"Tenant Rep","page":"rrg_loi_builder.html","sub":"build, version, send and negotiate letters of intent — lease or business sale","guide":"","feats":[{"id":"build","ic":"🧱","t":"Build an LOI in minutes","d":"Pick Tenant Rep or Business Sale, fill key info and terms, tick optional sections, and Build LOI assembles an editable letter."},{"id":"prefill","ic":"📍","t":"Fill from a space or engagement","d":"Pick a space from Spaces to fill property, suite, SF, rent and NNN; started from an engagement, the tenant fills in too."},{"id":"versions","ic":"🗃️","t":"Versions with what-changed","d":"Saving a letter again creates v2, v3… — every earlier version is kept, and Manage shows exactly which terms moved."},{"id":"files","ic":"⬇️","t":"PDF and Word downloads","d":"Download a letterhead PDF to send or a Word file for redlines — built from the version you edited on screen."},{"id":"send","ic":"✉️","t":"Send it tracked, with a deadline","d":"Email the PDF with your signature; opens are tracked, it's logged on the contact, marked Sent, and the response date becomes a task."},{"id":"nego","ic":"🤝","t":"Negotiate term by term","d":"In Manage, mark each term Proposed, Accepted, Countered or Rejected, log rounds sent and received, and move the status."},{"id":"counter","ic":"🔁","t":"AI reads their counter","d":"Paste the landlord's or seller's response and AI lists which terms moved, from what to what — one click applies it and logs the round."},{"id":"parse","ic":"📥","t":"Fill from a received LOI","d":"Paste an LOI someone sent you and AI pulls the parties and key terms into the builder, with a short summary."},{"id":"aicheck","ic":"✨","t":"AI section picks and draft review","d":"Suggest ticks the clauses this deal needs and proposes new ones; Review draft flags weak terms and gaps by severity."},{"id":"compare","ic":"⚖️","t":"Side-by-side lease comparison","d":"Every lease LOI on an engagement in one table — rent, escalations, free rent, TI and net effective rent, best deal marked."},{"id":"listing","ic":"🏷️","t":"Buyer LOI from a listing","d":"Opened from a business-sale listing, the LOI pre-loads the business, seller and asking price plus the seller's preferred terms."},{"id":"library","ic":"📚","t":"Clause library and defaults","d":"LOI managers maintain the clauses, standard terms and default values every rep builds from — via Manage clause library.","admin":true}]},"tours":{"label":"Tours","group":"Tenant Rep","page":"rrg_tours.html","sub":"every space shown to every tenant, their reaction, and a client-ready tour summary","guide":"","feats":[{"id":"log","ic":"📝","t":"Log tours on the engagement","d":"Each space shown is logged on the tenant's engagement under Location Tours — rents, SF, reaction, a 1–5 rating and their thoughts."},{"id":"list","ic":"🗂️","t":"Every tour in one list","d":"All tours across your tenant searches with gross $/SF worked out — filter by tenant or reaction, or search the notes."},{"id":"toppick","ic":"⭐","t":"Reactions and the top pick","d":"Loved, Liked, Maybe or Passed plus a star rating rank each space; the best-rated space not passed becomes the top pick."},{"id":"summary","ic":"🖨️","t":"Client tour summary","d":"Turn one tenant's tours into a ranked summary with the top pick and your notes — print it or save it as a PDF."},{"id":"notes","ic":"🗒️","t":"Overall notes and next steps","d":"Write the front-runner, backups and next moves on the summary — it saves as you type and prints with it."},{"id":"import","ic":"📦","t":"Bring over old Tour Tracker logs","d":"Tours saved by the old browser-only Tour Tracker show up here once — match each client to an engagement and import them."}]},"landlord_rep":{"label":"Space Listings","group":"Landlord Rep","page":"rrg_landlord_rep.html","sub":"represent a landlord — list a space for lease, market it, work tenants to a signed lease","guide":"rrg_landlordrep_help.html","feats":[{"id":"list","ic":"🏢","t":"One list of your spaces","d":"Every space you're marketing for lease — landlord, market, size, asking rent, status and last activity at a glance.","href":"rrg_landlordrep_help.html#overview"},{"id":"new","ic":"➕","t":"Start a space listing","d":"Name the space, its market and the landlord contact — it builds the file, links the landlord and opens the listing.","href":"rrg_landlordrep_help.html#new"},{"id":"space","ic":"📐","t":"Space details","d":"Size, asking rent, lease term, condition, suitable use, available date and key features live on the listing file.","href":"rrg_landlordrep_help.html#space"},{"id":"pipeline","ic":"🚦","t":"Landlord pipeline","d":"Move each space from Listing Setup → Marketing → Tours → LOI Received → Lease Negotiation → Executed.","href":"rrg_landlordrep_help.html#pipeline"},{"id":"tenants","ic":"🧲","t":"Work the tenant prospects","d":"Log tours and LOIs on the listing file and move each prospect toward a signed lease.","href":"rrg_landlordrep_help.html#tenants"},{"id":"docs","ic":"🔐","t":"Documents and data room","d":"A Documents card for the site plan, floor plan, lease and exhibits, plus the listing's own data room and its activity, right on the file.","href":"rrg_landlordrep_help.html#docs"},{"id":"report","ic":"📧","t":"Activity report for the landlord","d":"Send the landlord a leasing summary — tenant inquiries, showings, LOIs and room views — whenever you click Send now."}]},"property_listings":{"label":"Property Listings","group":"Landlord Rep","page":"rrg_property_listings.html","sub":"real estate for sale or lease — the dirt and the building, not the business","guide":"","feats":[{"id":"add","ic":"🏠","t":"Add a property listing","d":"Name, address, type, for sale or lease, status and photo — then sale economics, lease terms, building and land in tidy sections."},{"id":"fit","ic":"🍳","t":"Restaurant fit and infrastructure","d":"Record drive-thru, end-cap, pad, hood and grease, patio, 2nd-gen status, former use and liquor-license notes."},{"id":"enrich","ic":"✨","t":"Enrich from documents","d":"Reads the attached OM or brochure, verifies the address and pulls county parcel data to fill the physical fields — blanks only."},{"id":"costar","ic":"📋","t":"CoStar / LoopNet entry sheet","d":"Builds a field-by-field sheet labeled to match CoStar and LoopNet — copy each value straight in, or email it to the rep who posts."},{"id":"marketplace","ic":"🌐","t":"Publish to the marketplace","d":"Tick Show on the public marketplace to list it openly with address, price and photos — or feature it near the top."},{"id":"board","ic":"🚦","t":"Work it on the board","d":"One click puts the property on the Property Sales pipeline as a listing, with stages, tasks and offers like any other deal."},{"id":"docs","ic":"📎","t":"Documents and map","d":"Attach the OM, rent roll, survey and environmentals to the property, and see it pinned on a map from its address."}]},"centers":{"label":"Centers","group":"Landlord Rep","page":"rrg_centers.html","sub":"your book of shopping centers — co-tenancy, traffic, demographics and the spaces in each","guide":"","feats":[{"id":"record","ic":"🏬","t":"One record per center","d":"Name, address, type, GLA, anchors, co-tenants, landlord, traffic and notes — with a photo — for every center you work."},{"id":"spaces","ic":"🔗","t":"Spaces linked to each center","d":"The Spaces column shows how many spaces sit in each center and their status, so you see what's open where."},{"id":"enrichall","ic":"✨","t":"Enrich every center at once","d":"Fills address, city, metro, type, anchor and a photo for all centers from your own listings — and Google, when it's set up."},{"id":"brochures","ic":"📑","t":"Auto-fill from brochures","d":"Reads the flyers on a center's linked spaces and fills restaurant fit, contacts and leasing economics, and files the brochures."},{"id":"fit","ic":"🍳","t":"Restaurant fit and infrastructure","d":"Drive-thru, end-cap, pad, hood and grease, patio, 2nd-gen, the restaurants already there and liquor-license notes."},{"id":"demo","ic":"👥","t":"Demographics and Placer.ai","d":"Population at 1, 3 and 5 miles, daytime population and income — paste a Placer.ai report and AI pulls the key figures."},{"id":"contacts","ic":"📇","t":"Contacts and leasing economics","d":"Asking rent range, NNN, occupancy and open suites, plus the landlord, property manager and leasing broker for each center."},{"id":"docs","ic":"📎","t":"Documents and map","d":"Attach site plans, rent rolls and aerials to the center, and see it pinned on a map from its address."}]},"mass_studio":{"label":"Campaigns","group":"Marketing","page":"rrg_mass_studio.html","sub":"build, test, schedule and track email blasts to your subscriber lists","guide":"","admin":true,"feats":[{"id":"compose","ic":"✉️","t":"Build a branded blast","d":"Block editor with your logo and colors, or raw HTML. Merge first name, and the unsubscribe footer is added for you."},{"id":"listing","ic":"🏷️","t":"Pull from a listing","d":"Search a listing by name and the email fills itself in: business, asking price, market, listing # and status."},{"id":"audience","ic":"🎯","t":"Pick the audience","d":"Send to every active subscriber or one list, like Restaurants or Brokers. Suppressed addresses are always left out."},{"id":"test","ic":"🧪","t":"Test send, then send","d":"Send a proof to your own inbox, then send to the whole audience. You'll watch the counts on a live status card."},{"id":"schedule","ic":"🗓️","t":"Schedule a series","d":"Pick daily, weekly or monthly repeats. Weekends and holidays roll to the next business day and you see every date before you save."},{"id":"cadence","ic":"⚡","t":"Standard cadence in one click","d":"Fills your firm's usual drip, 12 weekday sends by default, with holidays skipped. Change any date before you save."},{"id":"queue","ic":"⏰","t":"Scheduled queue","d":"Every pending blast in one place with date, time, audience and recipient count. Reschedule or cancel from the row."},{"id":"ab","ic":"🔀","t":"A/B subject test","d":"Test two subject lines on a slice of the list. After the wait you set, the winner goes to everyone else."},{"id":"results","ic":"📈","t":"Results on every blast","d":"Opens, clicks, unsubs, complaints and bounces for each campaign, plus firm-wide totals. Export recipients to CSV."},{"id":"history","ic":"📜","t":"Send-by-send history","d":"For a blast that went out more than once, see recipients, opens and drop-offs for each send, plus a running total."},{"id":"calendar","ic":"📅","t":"Team blast calendar","d":"A private calendar link that puts every scheduled and recent blast on the team's phones, Google or Outlook, and keeps it updated."},{"id":"suppress","ic":"✖","t":"Unsubscribes handled for you","d":"Bounces, spam complaints and one-click unsubscribes are blocked automatically. Paste in anyone who asked off another way."},{"id":"manage","ic":"🗂️","t":"Archive, restore, delete","d":"Move old campaigns out of view without losing their numbers. Deleting a sent campaign means typing DELETE."}]},"mail_subscribers":{"label":"Subscribers","group":"Marketing","page":"rrg_mail_subscribers.html","sub":"your email audience: import it, slice it into lists and keep it clean","guide":"rrg_subscribers_help.html","admin":true,"feats":[{"id":"import","ic":"📥","t":"Import any list","d":"Paste or upload a CSV. It finds the email column on its own, tags the batch Brokers or Restaurants, and can drop it into a list.","href":"rrg_subscribers_help.html#add"},{"id":"tiles","ic":"📊","t":"Counts that filter","d":"Total, active, unsubscribed and bounced at a glance. Tap Brokers, Restaurants or Untyped to pull up that group.","href":"rrg_subscribers_help.html#segment"},{"id":"filter","ic":"🔎","t":"Search and filter","d":"Find anyone by email, name, type, area, list or source. Filters stack: status, type, area, list, source and date added.","href":"rrg_subscribers_help.html#segment"},{"id":"lists","ic":"☰","t":"Lists you can send to","d":"Tick subscribers and Add to list, or manage lists under ☰ Lists. Every list shows up in a campaign's Send to picker.","href":"rrg_subscribers_help.html#add"},{"id":"bulk","ic":"🚫","t":"Bulk unsubscribe or restore","d":"Tick rows and unsubscribe them from every list at once, or restore addresses that were taken off by mistake."},{"id":"record","ic":"👤","t":"Subscriber record","d":"Click any address to edit name, type, status, areas and lists, and see why an address was suppressed.","href":"rrg_subscribers_help.html#detail"},{"id":"engagement","ic":"📬","t":"Who opened what","d":"On each record: every campaign that person got, when it went out, when they opened it and whether they clicked.","href":"rrg_subscribers_help.html#engagement"},{"id":"areas","ic":"📍","t":"Areas and self-service preferences","d":"Each subscriber gets all areas or only chosen metros. Every email links to a page where they can update this themselves.","href":"rrg_subscribers_help.html#prefs"},{"id":"website","ic":"🌐","t":"Website sign-ups flow in","d":"Website listing-alert sign-ups are added automatically, typed Broker or Restaurant with the markets they picked."},{"id":"export","ic":"⬇️","t":"Export and print","d":"Download the filtered list (or just the ticked rows) as a CSV, or print it. You need the Export & print permission."},{"id":"legacy","ic":"🧹","t":"Retire the old subscriber list","d":"If records from the old, pre-Studio list are left, copy them in with their opt-outs and retire the old list."}]},"email_templates":{"label":"Email Templates","group":"Marketing","page":"rrg_email_templates.html","sub":"write your go-to emails once and drop them into any contact email or automation","guide":"rrg_email_templates_help.html","feats":[{"id":"reuse","ic":"✍️","t":"Write once, send from any contact","d":"Pick a template in a contact's email composer. Subject, body and attachments fill in; names merge in when you send.","href":"rrg_email_templates_help.html#reuse"},{"id":"tokens","ic":"🔑","t":"Merge fields","d":"Tokens like {{first_name}}, {{company}}, {{listing_name}} and {{my_phone}} fill in from the contact and from you when you send.","href":"rrg_email_templates_help.html#tokens"},{"id":"visibility","ic":"👥","t":"Personal or firm-wide","d":"Keep a template to yourself, or have an admin publish it as Shared so the whole team sends the same message.","href":"rrg_email_templates_help.html#visibility"},{"id":"folders","ic":"🗂️","t":"Folders","d":"Group the library into team-wide folders. Click one to filter, and hover to rename or delete it.","href":"rrg_email_templates_help.html#folders"},{"id":"inline","ic":"✏️","t":"Edit right in the list","d":"Click a name, folder, subject or visibility cell to change it in place. The body is never touched.","href":"rrg_email_templates_help.html#inline"},{"id":"attachments","ic":"📎","t":"Attachments ride along","d":"Attach a PDF, Word file or image to a template once, and it goes out every time the template is used."},{"id":"starters","ic":"📚","t":"Starter buyer and seller emails","d":"The firm library comes with Shared starter emails covering the buyer inquiry flow, the seller listing process and more."},{"id":"automations","ic":"⚙️","t":"Start automation emails from one","d":"In an automation's email step, choose Start from a template to load its subject and body."}]},"admin_automations":{"label":"Automations","group":"Marketing","page":"rrg_admin_automations.html","sub":"follow-up sequences that email, assign tasks and nudge reps for you","guide":"","admin":true,"feats":[{"id":"build","ic":"🧩","t":"Build a step-by-step sequence","d":"Stack up to 30 steps, set the wait before each one in days, hours and minutes, and drag them into order."},{"id":"email","ic":"✉️","t":"Emails that send themselves","d":"Personalized emails from the firm address with opens tracked. Contacts who unsubscribed or have no email are skipped."},{"id":"task","ic":"✅","t":"Tasks for the rep","d":"Drop a to-do like Call {{first_name}} about their search on the enrolling rep's list, due that day."},{"id":"notify","ic":"🔔","t":"Heads-up by email or text","d":"Ping the rep or any teammate by email or text when it's time to act, or pop an alert on the rep's screen. Text needs SMS set up."},{"id":"deal","ic":"⇉","t":"Move the deal forward","d":"Log an activity, set a listing's status and stage, mark it live, move it into a pipeline, or add a referred contact."},{"id":"timeline","ic":"⏱️","t":"Process timeline","d":"See every step with its gap and running total, plus the total length of the sequence."},{"id":"enroll","ic":"⟳","t":"How contacts get enrolled","d":"Reps enroll from a contact. Listing leads, Gmail intake, screening calls, bookings and signed agreements can enroll too."},{"id":"visibility","ic":"👥","t":"Shared or private","d":"Shared automations show up for every rep to enroll contacts in. Private ones only show up for you and other admins."},{"id":"sms","ic":"📱","t":"Text notifications","d":"One switch lets notify steps text the rep's phone instead of emailing. It needs Twilio set up first."}]},"commission":{"label":"Commissions","group":"Financials","page":"rrg_commission.html","sub":"your commission statement — what you've earned, been paid and are still owed","guide":"","feats":[{"id":"statement","ic":"💵","t":"Your earned-to-date statement","d":"Six tiles up top: your net earned, owed to you, paid to you, pipeline net, gross on your closings, and referral/co-broke paid out."},{"id":"waterfall","ic":"🪜","t":"Deal-by-deal commission waterfall","d":"Each deal shows GCI, referral off the top, co-broke share, company dollar, your split and your net — no spreadsheet needed."},{"id":"owed","ic":"⏳","t":"Owed vs. paid, pro-rated","d":"Owed to you tracks your share of what the firm hasn't collected yet, pro-rated to what's been received on each deal."},{"id":"pipeline","ic":"🔭","t":"Projected net on open deals","d":"Open deals get their own table so you can see what your pipeline is worth to you, not just to the firm."},{"id":"year","ic":"📅","t":"All time or this year","d":"Flip to This year and every tile and table follows: deals closed this year plus open deals expected to close by year-end."},{"id":"csv","ic":"⬇️","t":"Export CSV","d":"Download the whole statement — every deal's waterfall, paid and owed — as a spreadsheet for your accountant or your own records."},{"id":"deallink","ic":"🔗","t":"Jump to the deal file","d":"Click any deal name to open its listing file, where the commission numbers behind the statement are entered."},{"id":"anyrep","ic":"👥","t":"Pull any rep's statement","d":"Admins get a rep picker to open anyone's statement — handy at payout time or for a split question.","admin":true}]},"invoices":{"label":"Invoices","group":"Financials","page":"rrg_invoices.html","sub":"bill commissions and fees, record payments, and see what's still outstanding","guide":"","admin":true,"feats":[{"id":"newinv","ic":"🧾","t":"Bill a deal in a few clicks","d":"+ New invoice: pick the deal, the bill-to and the line items — the invoice number, totals and balance fill in for you."},{"id":"fromdeal","ic":"🔗","t":"Start an invoice from the deal","d":"Create invoice on a deal pre-fills the listing, bill-to and commission amount — and the deal's commission status follows its invoices."},{"id":"terms","ic":"📆","t":"Terms set the due date","d":"Pick Net 10/15/30 or Due on receipt and the due date fills itself; broker terms like Due at Closing are there too."},{"id":"items","ic":"📦","t":"Saved items & services","d":"Pick a saved line — description, rate and income account already set — from + Add item / service instead of retyping it."},{"id":"payments","ic":"💳","t":"Record payments, status follows","d":"Log a check, wire or card payment against the invoice; Paid, Partial and the balance update on their own."},{"id":"paylink","ic":"🌐","t":"Online pay link (card or ACH)","d":"With Stripe on, each invoice gets a secure link the client pays by card or bank — the payment and fee record themselves."},{"id":"recurring","ic":"🔁","t":"Recurring invoices","d":"Set an invoice to repeat weekly to yearly and a new Sent invoice is generated each period from its lines."},{"id":"tax","ic":"🧮","t":"Sales tax line","d":"Add a tax label and rate and the invoice adds the tax on top; the firm default fills in on every new invoice."},{"id":"totals","ic":"📊","t":"Billed, collected, outstanding","d":"The tiles up top total what's billed, collected and still owed — and follow your search and filters."},{"id":"books","ic":"📒","t":"Posts to the books","d":"Sent invoices and their payments post themselves to the General Ledger — no double entry for your bookkeeper."}]},"payments":{"label":"Payments","group":"Financials","page":"rrg_payments.html","sub":"every payment received against an invoice, in one ledger","guide":"","admin":true,"feats":[{"id":"ledger","ic":"📒","t":"One ledger of every payment","d":"Date, invoice, deal, payer, method and amount for every payment on every invoice, newest first."},{"id":"totals","ic":"💰","t":"Collected, this year, count","d":"Tiles show total collected, this calendar year and the payment count — payments on voided invoices set apart — and follow your filters."},{"id":"toinvoice","ic":"🧾","t":"Click through to the invoice","d":"Every invoice number opens that invoice in Invoices, where its payments are added, fixed or removed."},{"id":"online","ic":"🌐","t":"Online payments land on their own","d":"When a client pays an invoice's online link, the payment shows up here automatically as Online (Stripe)."},{"id":"filters","ic":"🔎","t":"Filter by method, deal, payer, date","d":"Narrow to a method, deal, bill-to or date range; search also matches check numbers and references."},{"id":"export","ic":"⬇️","t":"Export or print the ledger","d":"Send the payment list to CSV or print it for the bookkeeper — available if your login has export rights."}]},"expenses":{"label":"Expenses","group":"Financials","page":"rrg_expenses.html","sub":"log deal and office spend, charge it to a listing, and track what's paid or reimbursable","guide":"","admin":true,"feats":[{"id":"log","ic":"➕","t":"Log an expense in seconds","d":"+ New expense: date, vendor, category, amount, method and status — save and it's on the ledger."},{"id":"listing","ic":"🏷️","t":"Charge it to a deal","d":"Tie an expense to a listing and it shows in that deal's expenses on the listing file — real cost per deal."},{"id":"status","ic":"✅","t":"Unpaid, paid, reimbursable","d":"Track whether each bill is Unpaid, Paid or Reimbursed, and flag spend a client or rep should get back."},{"id":"receipt","ic":"📎","t":"Receipt link or reference","d":"Paste a Drive/Dropbox link, check number or note so the backup is one click away."},{"id":"categories","ic":"🗂️","t":"Categories feed P&L and the ledger","d":"Each category maps to an expense account, so P&L and the General Ledger sort your spend with no extra work."},{"id":"filters","ic":"🔎","t":"Filter and the totals follow","d":"Narrow by category, status, method, listing or date range — the tiles recalculate for just what's shown."},{"id":"team","ic":"👥","t":"The whole team's spend","d":"Admins see every rep's expenses with a Logged by column; reps only ever see their own."}]},"pnl":{"label":"Profit & Loss","group":"Financials","page":"rrg_pnl.html","sub":"revenue, expenses and net income for any period, on cash or accrual basis","guide":"","admin":true,"feats":[{"id":"statement","ic":"📈","t":"One-page P&L","d":"Revenue, operating expenses and net income for the period, with the bottom line in green or red."},{"id":"period","ic":"📅","t":"Pick the period","d":"This month, this quarter, this year, last year or all time — the whole statement rebuilds instantly."},{"id":"basis","ic":"⚖️","t":"Cash or accrual basis","d":"Show revenue when it's invoiced or when it's collected — the firm setting drives it, and the page labels which."},{"id":"ar","ic":"⏳","t":"Invoiced, collected, outstanding A/R","d":"Side figures show what was billed and collected this period and the total still owed across all open invoices."},{"id":"bycat","ic":"🗂️","t":"Revenue and expenses by account","d":"Every income and expense account with activity gets its own line, with its code, so you see where the money comes from and goes."},{"id":"print","ic":"🖨️","t":"Print it","d":"One click prints a clean copy of the statement for the partners or the CPA."}]},"gl":{"label":"General Ledger","group":"Financials","page":"rrg_gl.html","sub":"double-entry books built from your invoices, payments and expenses","guide":"","admin":true,"feats":[{"id":"autopost","ic":"⚙️","t":"Posts itself from the deal books","d":"Sent invoices, payments and expenses become journal entries automatically — A/R, cash, income, tax and fees all land right."},{"id":"trial","ic":"⚖️","t":"Trial balance with a balance check","d":"Every account's debits, credits and balance, with an In balance ✓ check and a switch to roll sub-accounts into parents."},{"id":"journal","ic":"📓","t":"Journal of every entry","d":"Every entry, newest first, tagged Invoice, Payment, Expense or Manual — with each line's account, debit and credit."},{"id":"manual","ic":"✍️","t":"Manual journal entries","d":"＋ New journal entry for anything that isn't an invoice or expense — it won't save unless debits equal credits."},{"id":"ledger","ic":"🔍","t":"Running ledger per account","d":"Pick an account to see every posting to it with a running balance — sub-accounts included when roll-up is on."},{"id":"coa","ic":"🗂️","t":"Chart of accounts with sub-accounts","d":"Add, rename and nest accounts under parents; core accounts are protected so the auto-posting never breaks."},{"id":"qbimport","ic":"⇪","t":"Import from QuickBooks","d":"Paste or upload a QuickBooks chart-of-accounts CSV — types are mapped and you preview before anything is added."},{"id":"csv","ic":"⬇️","t":"Export any tab to CSV","d":"Export CSV downloads whichever tab you're on — trial balance, journal, an account ledger or the chart — ready for Excel."},{"id":"danger","ic":"🧨","t":"Reset the books","d":"Danger zone: wipe manual entries, reset to the starter chart, or clear everything — auto-posted entries are untouched."}]},"market_radar":{"label":"Alcohol Sales","group":"Tools","page":"rrg_market_radar.html","sub":"state alcohol sales for every bar and restaurant — spot sellers, vacancies and growers","guide":"","feats":[{"id":"city","ic":"🏙️","t":"Load any Texas city","d":"Type a city and every operator filing mixed-beverage taxes there loads — sales, trend, mix and status, cached for a day."},{"id":"views","ic":"⚡","t":"Quick views","d":"One click for Stopped filing, Sales down 25%+, Growing 25%+, New operators, Pending permits or the credit-law list — with counts."},{"id":"filters","ic":"🎚️","t":"Filter on what matters","d":"Sales change over 3, 6 or 12 months, monthly sales range, months since last filing, zip codes, liquor share and filing history."},{"id":"chains","ic":"🔗","t":"Roll up franchises and chains","d":"Consolidate locations into one row by brand name or by owner — combined sales and trend, expandable to every location."},{"id":"operator","ic":"🏢","t":"Operator page","d":"Click any operator for a 24-month chart, monthly and yearly tables with % change, revenue mix, permits at the address and rankings."},{"id":"holder","ic":"📇","t":"Permit holder and Add to CRM","d":"See the permit holder, owner of record, phone, mailing address and permit status — and add the owner to your CRM in one click."},{"id":"ai","ic":"✨","t":"AI broker read","d":"One click writes a short broker read — bottom line, trend, mix, ownership, signals and next moves — saved for the whole team."},{"id":"compare","ic":"⇄","t":"Compare up to five locations","d":"Tick operators, or use ⇄ Compare on an operator page, to see sales, change, mix, rank and permit side by side on a shared chart."},{"id":"pdf","ic":"📄","t":"Comparison PDF report","d":"Turn a comparison into a letterhead PDF with your title, who it's prepared for and broker notes on top."},{"id":"track","ic":"📌","t":"Track as a space","d":"Turn a stopped or sliding operator into an off-market, second-gen space in Spaces, with the filing signal in its notes."},{"id":"export","ic":"⬇️","t":"Export CSV","d":"Download the current filtered list — or the pending-permit or credit-law list — with every metric, chain roll-ups included."},{"id":"source","ic":"⚙️","t":"Data source setting","d":"Admins set the state open-data portal and dataset IDs, test the connection, or switch the feature off under Integrations.","admin":true}]},"lease_queue":{"label":"Lease Abstracts","group":"Tools","page":"rrg_lease_queue.html","sub":"upload a lease, get a buyer-ready abstract of term, rent, options, assignment and guaranty","guide":"","feats":[{"id":"ai-read","ic":"🤖","t":"AI reads the lease for you","d":"Upload the lease and amendments; the analyst pulls term, rent, options, NNN, assignment and guaranty in a minute or two."},{"id":"room-lease","ic":"🗂️","t":"Uses the lease already in the room","d":"Link a listing whose data room already holds the lease and you can build without uploading it again."},{"id":"manual","ic":"✍️","t":"Start blank and type it in","d":"No lease file handy? Fill the abstract in by hand on the same form the AI uses."},{"id":"edit","ic":"📝","t":"Edit in place, saves itself","d":"Click any value on the abstract and type; it autosaves, and you can add watch items, rent periods and critical dates."},{"id":"watch","ic":"🚩","t":"Watch items and critical dates","d":"The deal-killers float to the top: short runway, no options, guaranty, recapture, consent — plus every notice deadline."},{"id":"occupancy","ic":"📉","t":"Occupancy cost as % of sales","d":"Add annual sales and the abstract grades occupancy cost: green at 10% or under, amber to 15%, red above."},{"id":"redact","ic":"🕶️","t":"Redact landlord and tenant","d":"Hide party names so the abstract is safe to share before an NDA — both are on by default."},{"id":"filing","ic":"📎","t":"Filed to the contact and data room","d":"Link a contact and listing and the finished abstract lands as a PDF in their Documents and in the room under Lease."},{"id":"feeds","ic":"🔗","t":"Feeds the Marketing Pack and BOV","d":"The abstract fills the CIM's occupancy and lease summary and the valuation's lease read — no retyping."},{"id":"list","ic":"📋","t":"Term left at a glance","d":"The list shows months left, option months and expiration for every abstract, with bulk delete."}]},"calculators":{"label":"Calculators","group":"Tools","page":"rrg_calculators.html","sub":"cap rate, sale and lease commissions, and net effective rent — the quick deal math","guide":"","feats":[{"id":"caprate","ic":"📐","t":"Solve value, NOI or cap rate","d":"Enter any two of value, NOI and cap rate and it solves the third — handy when a seller quotes a price and you need the implied cap."},{"id":"sensitivity","ic":"📊","t":"Cap rate sensitivity table","d":"Value at caps one point either side of yours, in quarter-point steps, with the dollar and percent swing."},{"id":"salecomm","ic":"💵","t":"Tiered sale commission","d":"Type a sale price and get gross commission off the firm's tiered rate card — each slice of price earns its own tier's rate."},{"id":"overrides","ic":"✏️","t":"Per-deal rate overrides","d":"Type over any tier rate or threshold to model a negotiated fee for one deal; Reset rate card puts the firm schedule back."},{"id":"firmcard","ic":"💾","t":"Save as firm rate card","d":"Admins can turn the tiers on screen into the firm's rate card, so every rep's forecaster loads the new schedule.","admin":true},{"id":"split","ic":"🤝","t":"Agent / house split and referrals","d":"Shows what you take home and what the house keeps after any referral — at the firm's agent split, or yours; admins can override."},{"id":"leasecomm","ic":"🏬","t":"Lease commission over the term","d":"Commission on every year of base rent with escalations compounding, plus an optional reduced rate after a set year."},{"id":"ner","ic":"🧮","t":"Net effective rent","d":"Turns free rent and TI into the tenant's true average rent per SF, and adds NNN for a total occupancy number."},{"id":"print","ic":"🖨️","t":"Print a branded one-pager","d":"Name the deal and hit Print for a clean RRG-branded sheet of the numbers — save it as a PDF to send."}]},"email_finder":{"label":"Email Finder","group":"Tools","page":"rrg_email_finder.html","sub":"pull restaurants by city or ZIP from Google, then find the emails on their websites","guide":"","admin":true,"feats":[{"id":"search","ic":"🔎","t":"Find restaurants by area and type","d":"Search a city and state for any cuisine or style, from BBQ to wine bars, and get name, address, phone, website and rating."},{"id":"zip","ic":"📮","t":"Exact ZIP search","d":"Search up to 12 ZIP codes at once. Results outside each ZIP are dropped, so you get just that neighborhood."},{"id":"region","ic":"🗺️","t":"Region presets","d":"One pick fills the ZIPs for a San Antonio trade area, like Stone Oak or Medical Center, and names the list for you."},{"id":"stack","ic":"➕","t":"Searches stack into one list","d":"Each new search adds to the list on screen and skips repeats, so several types or ZIPs build one combined list."},{"id":"emails","ic":"✉️","t":"Find the emails","d":"Reads each website's home, contact, about and reservations pages and picks the best address on the restaurant's own domain."},{"id":"save","ic":"💾","t":"Saved lists","d":"Save a list, reopen it to keep working and save changes, download it as CSV or delete it. Each shows emails found against total rows."},{"id":"export","ic":"⬇️","t":"Export to CSV for Campaigns","d":"Download the list with name, email, phone, website, address and rating, then import it on the Subscribers page."}]},"tracked_emails":{"label":"Tracked Emails","group":"Tools","page":"rrg_tracked_emails.html","sub":"every email you sent to a contact, and who opened it","guide":"","feats":[{"id":"log","ic":"📨","t":"Every email to a contact, in one log","d":"Emails from contact pages, automations and Gmail, each with the contact, company, sender and when it went out."},{"id":"opens","ic":"👁️","t":"Opens you can trust","d":"Counts opens on app-sent email, but ignores opens from your own IP address and anything in the first 20 seconds after sending."},{"id":"detail","ic":"🕒","t":"Open-by-open detail","d":"Hover or click an open count to see each open's time and whether it came from a phone or a desktop."},{"id":"read","ic":"📖","t":"Click a subject to read it","d":"Open the exact email that went out, with To, Cc, sender, open status and a link to the contact."},{"id":"gmail","ic":"⟳","t":"Pull in your Gmail sends","d":"Add the last 90 days of your Gmail Sent mail to the right contacts. Untracked Gmail emails stay hidden until you ask for them."},{"id":"stats","ic":"📊","t":"Your open rate at a glance","d":"Tiles for emails sent, how many were tracked, how many were opened, and your open rate on tracked sends."}]},"feedback":{"label":"Wish List","group":"Admin","page":"rrg_feedback.html","sub":"log feature requests and bugs, vote them up, and track each one from approved to shipped","guide":"","feats":[{"id":"new","ic":"➕","t":"Log a request or bug","d":"Give it a short title, pick the type and priority, and describe what you need — it lands as New for an admin to review."},{"id":"filter","ic":"🔎","t":"Status tiles and search","d":"Click a count tile to see only Open, Approved, In progress or Shipped; narrow by type or search title, detail and person."},{"id":"vote","ic":"▲","t":"Vote up what matters","d":"Click ▲ to push a request up — one vote each, click again to take it back; sort the Votes column to see what the team wants most."},{"id":"inline","ic":"✏️","t":"Change type, priority or status","d":"Admins click the Type, Priority or Status cell on any row to change it on the spot — no form to open.","admin":true},{"id":"replies","ic":"↩️","t":"Claude's replies on the request","d":"When an item is worked, Claude's note shows right under it with the approved and sent dates."},{"id":"approve","ic":"✅","t":"Approve what gets built","d":"Admins click Approve on a New request to queue it for the next batch, or Unapprove to send it back.","admin":true},{"id":"send","ic":"✈️","t":"Send approved batch to Claude","d":"One click builds a brief of every approved request to paste into Claude, then marks them Sent.","admin":true},{"id":"paste","ic":"⇤","t":"Paste Claude's update back","d":"Paste Claude's one-line-per-item reply and every request's status and note update at once.","admin":true}]},"tickets":{"label":"Office Requests","group":"Admin","page":"rrg_tickets.html","sub":"ask the office for signage, collateral, photos, compliance or IT — answered right away","guide":"","feats":[{"id":"new","ic":"✉️","t":"Open a request to the office","d":"Pick the department, category and priority, say what you need, and it's routed to the right team by email."},{"id":"ai","ic":"🤖","t":"Answered on the spot","d":"An AI office assistant reads every request the moment it's sent and answers, flags it for a person, or asks what's missing."},{"id":"thread","ic":"💬","t":"Reply in the thread","d":"Add detail or answer a question in the thread; the assistant answers again, and a person's reply emails you."},{"id":"due","ic":"⏰","t":"Due dates and overdue flags","d":"Every request gets a due date from its priority — Urgent next day, High two days, Normal five — and turns red when it slips."},{"id":"filters","ic":"🗂️","t":"Needs you, overdue, answered","d":"Count tiles and filter chips cut the list to what needs action now; the Opened column shows how long each has been open."},{"id":"files","ic":"📎","t":"Attach files","d":"Add PDFs, images, spreadsheets or Word files up to 20 MB to any request — artwork, site plans, the old sign photo."},{"id":"close","ic":"✔️","t":"Close or reopen","d":"Close a request when it's handled to keep the record; reopen it any time to add more."},{"id":"internal","ic":"🔒","t":"Private office notes","d":"Department members keep internal notes on a request that the requester never sees."},{"id":"admin","ic":"🛡️","t":"Office view: by requester, status","d":"Admins see every department's requests, can filter by who asked and set any status from the thread header.","admin":true}]},"team":{"label":"Team","group":"Admin","page":"rrg_team.html","sub":"every rep's book, production and commission on one screen, plus their employee records","guide":"rrg_team_help.html","admin":true,"feats":[{"id":"roster","ic":"📋","t":"Everyone at a glance","d":"One row per team member — listings, deals, GCI, received, waiting on, net and pipeline — sortable by any column.","href":"rrg_team_help.html#roster"},{"id":"kpis","ic":"📊","t":"Firm totals up top","d":"Active listings, deals, GCI year to date, deals that fell through, received, waiting on and pipeline for the whole team.","href":"rrg_team_help.html#kpis"},{"id":"owed","ic":"⏳","t":"Commission still owed","d":"Received vs. waiting on, per rep and firm-wide — e.g. the second half of a lease commission due at occupancy.","href":"rrg_team_help.html#kpis"},{"id":"record","ic":"👤","t":"One record per person","d":"Click a name for their employee record — production, listings, deals and agreements, each linked to the live record.","href":"rrg_team_help.html#overview"},{"id":"details","ic":"🪪","t":"Employee details","d":"Home address, LinkedIn, territory, start and end dates and emergency contact, kept on the record.","href":"rrg_team_help.html#details"},{"id":"commission","ic":"💰","t":"Net follows the commission split","d":"Each rep's Net runs through the commission waterfall at the firm agent split, or at their own split if an admin set one.","href":"rrg_team_help.html#commission"},{"id":"private","ic":"🛡️","t":"Private by design","d":"The roster and everyone's commission are admin-only; a rep sees only their own record.","href":"rrg_team_help.html#roster"},{"id":"add","ic":"➕","t":"Add a team member","d":"Create a login on the spot — name, username, role, title, phone and a temporary password they change on first sign-in.","admin":true,"href":"rrg_team_help.html#roster"},{"id":"remove","ic":"🗑️","t":"Deactivate a member, keep the book","d":"The trash icon deactivates their login and takes them off the roster; their listings, deals, records and history stay.","admin":true},{"id":"payroll","ic":"🔒","t":"Payroll and tax","d":"Payment method, W-9 on file, tax classification and 1099 details — visible only to administrators.","admin":true,"href":"rrg_team_help.html#payroll"}]},"settings":{"label":"Settings","group":"Admin","page":"rrg_settings.html","sub":"configure the platform — team access, pipelines, paperwork, branding, data, email and AI","guide":"rrg_admin_help.html","admin":true,"feats":[{"id":"hub","ic":"🧭","t":"Every admin tool in one rail","d":"Pick a tool on the left and it opens on the right; the link remembers which one, so you can bookmark or share it.","href":"rrg_admin_help.html#overview"},{"id":"users","ic":"👥","t":"Users, roles and permissions","d":"Add people, set what each role can see and do, override one person's switches, and hand a departing rep's book to someone else.","href":"rrg_admin_help.html#users"},{"id":"pipelines","ic":"🔀","t":"Pipelines, routing and automations","d":"Set the stages deals move through, which pipeline each deal type lands in, and follow-up sequences that run themselves.","href":"rrg_admin_help.html#pipelines"},{"id":"commission","ic":"💰","t":"Commission and accounting setup","d":"Set the tiered rate card, flat rate, per-location minimum fee and agent split, plus invoice terms, tax and payment methods."},{"id":"paperwork","ic":"📝","t":"Paperwork engine","d":"Agreement templates, LOI defaults and clause library, valuation rules and the call questionnaires reps run.","href":"rrg_admin_help.html#paperwork"},{"id":"roomsecurity","ic":"🔐","t":"Data room security defaults","d":"Require a one-time email code, alert the owner when a buyer opens the P&L or lease, and watermark every PDF download."},{"id":"calendar","ic":"📅","t":"Time zone and calendar features","d":"Set the firm's time zone, and switch Google sync, Meet links, booking links, calendar sharing and more on or off for everyone."},{"id":"branding","ic":"🎨","t":"Branding and white-label","d":"App name, dashboard announcement, logos for dark and light backgrounds, favicon and brand colors — pull logo and favicon from your site.","href":"rrg_admin_help.html#branding"},{"id":"integrations","ic":"🔌","t":"Email, texting and API keys","d":"Connect Google Maps, county parcel data, outbound email and Twilio texting, and set how often reps' Gmail sent mail is logged.","href":"rrg_admin_help.html#integrations"},{"id":"ai","ic":"🤖","t":"AI engine, prompts and usage","d":"Choose the AI model and key behind every generator, tune the prompts, and see what's been run and what it cost.","href":"rrg_admin_help.html#ai"},{"id":"data","ic":"🗃️","t":"Import, enrich and export","d":"Bring your book over from another CRM, enrich it from Google and AI, check record counts and export it all.","href":"rrg_admin_help.html#data"},{"id":"backup","ic":"🛡️","t":"Backups you can download","d":"Daily snapshots of every record and file, a fresh backup on demand, and a full restore from any snapshot or zip.","href":"rrg_admin_help.html#data"}]},"reports":{"label":"Reports","group":"Admin","page":"rrg_reports.html","sub":"leads, rep activity, data-room engagement and team logins for any time window","guide":"","admin":true,"feats":[{"id":"window","ic":"📅","t":"Pick the time window","d":"7 days, 30 days, 90 days or 12 months — every chart and table on every tab updates to that window."},{"id":"leads","ic":"📈","t":"Leads over time","d":"Overview: new leads, new companies, activities logged and total contacts, plus a day-by-day chart of new contacts."},{"id":"activity","ic":"📞","t":"Activity by rep","d":"Leads & Activity: a stacked bar per rep showing calls, emails, tours and more, with the counts in a table below."},{"id":"sources","ic":"🧲","t":"Where leads come from","d":"New leads broken out by lead source and by the rep who added them — see which channels and people feed the pipeline."},{"id":"docs","ic":"📂","t":"What buyers open in data rooms","d":"Data Room: views, downloads, unique buyers and read time for every document across every room."},{"id":"hot","ic":"🔥","t":"Hot-buyer call list","d":"Buyers who opened a key financial or lease document in the last 7 days get a HOT flag — your call-today list."},{"id":"usage","ic":"👥","t":"Logins and tool adoption","d":"Team & Usage: sign-ins, active users, failed logins and the most-used tools — see who's actually using the system."}]}};
